CREATE TEMP TABLE cli3619_restore_preserved(kind text PRIMARY KEY, rows jsonb) ON COMMIT DROP;
INSERT INTO cli3619_restore_preserved
SELECT 'other_resources',coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') FROM public.contract_resources r
WHERE contract_id<>'5298edb2-5f3e-4d76-88e3-72c14f44861b'
UNION ALL SELECT 'contract_headers',coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]') FROM public.client_contracts c
WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6'
UNION ALL SELECT 'attendance',coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM public.attendance_entries a
WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6'
UNION ALL SELECT 'payroll_runs',coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]') FROM public.payroll_runs p
WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6'
UNION ALL SELECT 'payroll_snapshots',coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]') FROM public.payroll_run_snapshots p
WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6'
UNION ALL SELECT 'masters',coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]') FROM public.cost_components m
WHERE id IN ('cc142930-0001-4001-8001-000000000001','ead64358-9d85-441a-ad99-b8ce35430ed5');
SELECT count(*)=2 AND bool_and((to_jsonb(r)-'updated_at')=o.row_data) AS already_original
FROM public.contract_resources r JOIN original_cli3619_rates o ON r.id=(o.row_data->>'id')::uuid
\gset
\if :already_original
\ir ../data-fixes/20261124_cli3619_verified_formulas.sql
\endif
\ir ../backups/cli3619-restore-20261124.sql
DO $test$
BEGIN
 IF (SELECT count(*) FROM public.contract_resources WHERE contract_id='5298edb2-5f3e-4d76-88e3-72c14f44861b')<>2
 OR EXISTS(SELECT 1 FROM original_cli3619_rates o LEFT JOIN public.contract_resources r ON r.id=(o.row_data->>'id')::uuid
  WHERE r.id IS NULL OR (to_jsonb(r)-'updated_at') IS DISTINCT FROM o.row_data) THEN
  RAISE EXCEPTION 'CLI3619 restoration must reproduce every original rate field exactly'; END IF;
 IF EXISTS(SELECT 1 FROM public.contract_resources WHERE contract_id='5298edb2-5f3e-4d76-88e3-72c14f44861b'
 AND (employer_contributions->0->>'calcType'<>'fixed' OR (employer_contributions->0->>'amount')::numeric<>1950
 OR deductions->0->>'costComponentId' IS NOT NULL OR employer_contributions->0->>'costComponentId' IS NOT NULL)) THEN
  RAISE EXCEPTION 'Both roles must have original fixed employer EPF and no trial master links'; END IF;
 IF (SELECT rows FROM cli3619_restore_preserved WHERE kind='other_resources') IS DISTINCT FROM
 (SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]') FROM public.contract_resources r WHERE contract_id<>'5298edb2-5f3e-4d76-88e3-72c14f44861b') THEN
  RAISE EXCEPTION 'Another client or historical rate changed'; END IF;
 IF (SELECT rows FROM cli3619_restore_preserved WHERE kind='contract_headers') IS DISTINCT FROM
 (SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]') FROM public.client_contracts c WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6') THEN
  RAISE EXCEPTION 'Contract header or approval changed'; END IF;
 IF (SELECT rows FROM cli3619_restore_preserved WHERE kind='attendance') IS DISTINCT FROM
 (SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') FROM public.attendance_entries a WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6') THEN
  RAISE EXCEPTION 'Source attendance changed'; END IF;
 IF (SELECT rows FROM cli3619_restore_preserved WHERE kind='payroll_runs') IS DISTINCT FROM
 (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]') FROM public.payroll_runs p WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6') THEN
  RAISE EXCEPTION 'Payroll approval metadata changed'; END IF;
 IF (SELECT rows FROM cli3619_restore_preserved WHERE kind='payroll_snapshots') IS DISTINCT FROM
 (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.id),'[]') FROM public.payroll_run_snapshots p WHERE unit_id='ccd79c30-057f-4fd0-af5d-026714d024d6') THEN
  RAISE EXCEPTION 'Settled payroll changed'; END IF;
 IF (SELECT rows FROM cli3619_restore_preserved WHERE kind='masters') IS DISTINCT FROM
 (SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.id),'[]') FROM public.cost_components m WHERE id IN ('cc142930-0001-4001-8001-000000000001','ead64358-9d85-441a-ad99-b8ce35430ed5')) THEN
  RAISE EXCEPTION 'Shared formula masters changed'; END IF;
END $test$;
ROLLBACK;
